style.img:
it falls back
      to the values below and follows prefers-color-scheme. */
   .fuji .rock { fill: var(--mark-rock, #5aa6c4); }
   .fuji .snow { fill: var(--mark-snow, #e3e9f1); }
   @media (prefers-color-scheme: light) {
     .fuji .rock { fill: var(--mark-rock, #266b87); }
     /* Not pure white: on a light ground the cap would vanish and the summit
        would read as a chunk cut out of the mountain. */
     .fuji .snow { fill: var(--mark-snow, #d9e7ee); }
   }
